#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

/*
   Compute the reverse prefix (suffix) sum of the vector `x` into `output`.
   For each index i, output[i] = sum_{j=i}^{n-1} x[j].

   The implementation is fully thread‑safe for any OpenMP thread count.
   It uses a two‑phase block‑wise scan that never writes the same
   location from multiple threads without proper synchronization.
*/
void reversePrefixSum(const std::vector<int>& x, std::vector<int>& output) {
    const std::size_t n = x.size();
    output.clear();
    output.resize(n);
    if (n == 0) return;

    /* --------------------------------------------------------------
       1. Block‑wise inclusive prefix sum (scan) of the original array.
       -------------------------------------------------------------- */
    std::vector<long long> prefix(n);                 // inclusive prefix sums
    int num_threads = 1;

    // Determine how many threads the runtime will actually use.
    #pragma omp parallel
    {
        #pragma omp single
        num_threads = omp_get_num_threads();
    }

    std::vector<long long> thread_sum(num_threads, 0); // total of each block
    std::vector<long long> offset(num_threads, 0);    // prefix of block totals

    // First parallel region: each thread processes a contiguous block,
    // builds a local inclusive prefix, and records the block total.
    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const std::size_t block_sz = (n + num_threads - 1) / num_threads; // ceil
        const std::size_t start = tid * block_sz;
        const std::size_t end   = std::min(start + block_sz, n);

        long long local = 0;
        for (std::size_t i = start; i < end; ++i) {
            local += static_cast<long long>(x[i]);
            prefix[i] = local;               // local (in‑thread) inclusive prefix
        }
        thread_sum[tid] = local;              // total of this block
    }

    // Compute the offset for each block (exclusive scan of block totals).
    for (int t = 1; t < num_threads; ++t) {
        offset[t] = offset[t - 1] + thread_sum[t - 1];
    }

    // Second parallel region: add the appropriate offset to every element
    // of the block that each thread owns.
    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const std::size_t block_sz = (n + num_threads - 1) / num_threads;
        const std::size_t start = tid * block_sz;
        const std::size_t end   = std::min(start + block_sz, n);
        const long long off = offset[tid];

        for (std::size_t i = start; i < end; ++i) {
            prefix[i] += off;
        }
    }

    /* --------------------------------------------------------------
       2. Convert inclusive prefix sums to reverse prefix (suffix) sums.
       -------------------------------------------------------------- */
    const long long total = prefix[n - 1];   // sum of all elements

    #pragma omp parallel for schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        long long sum_before = (i == 0) ? 0 : prefix[i - 1];
        output[i] = static_cast<int>(total - sum_before);
    }
}
