#include <vector>
#include <cstddef>
#include <omp.h>

/*
   Compute the reverse prefix (suffix) sum of the vector `x` into `output`.
   For each index i:
        output[i] = sum_{j=i}^{n-1} x[j]

   The implementation is race‑free for any OpenMP thread count.
   It uses a block‑wise exclusive scan to obtain, for every position,
   the sum of all elements that appear *before* it, then subtracts that
   from the total sum.
*/
void reversePrefixSum(const std::vector<int>& x, std::vector<int>& output) {
    const std::size_t n = x.size();
    output.clear();
    output.resize(n);
    if (n == 0) return;

    /* --------------------------------------------------------------
       1. Total sum of the whole vector (reduction, safe for any threads)
       -------------------------------------------------------------- */
    long long total = 0;
    #pragma omp parallel for reduction(+:total) schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        total += static_cast<long long>(x[i]);
    }

    /* --------------------------------------------------------------
       2. Block‑wise exclusive prefix sum (sum of elements before i)
       -------------------------------------------------------------- */
    int num_threads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        num_threads = omp_get_num_threads();
    }

    std::vector<long long> block_sum(num_threads, 0);      // sum of each block
    std::vector<long long> block_excl(num_threads, 0);     // exclusive prefix of block sums
    std::vector<long long> prefix_before(n);              // exclusive prefix for each element

    /* First parallel region: each thread processes a contiguous block,
       writes its exclusive prefix into `prefix_before`, and records the
       total of its block into `block_sum[tid]`. */
    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();

        // Compute start/end indices for this thread using a balanced distribution
        const std::size_t base   = n / static_cast<std::size_t>(num_threads);
        const std::size_t extra  = n % static_cast<std::size_t>(num_threads);
        const std::size_t start  = tid * base + std::min(static_cast<std::size_t>(tid), extra);
        const std::size_t length = base + (static_cast<std::size_t>(tid) < extra ? 1 : 0);
        const std::size_t end    = start + length;

        long long local = 0;                     // running sum within the block
        for (std::size_t i = start; i < end; ++i) {
            prefix_before[i] = local;            // sum of elements before i (within block)
            local += static_cast<long long>(x[i]);
        }
        block_sum[tid] = local;                  // total of this block
    }

    /* Build the exclusive prefix of block sums (offset for each block). */
    for (int t = 1; t < num_threads; ++t) {
        block_excl[t] = block_excl[t - 1] + block_sum[t - 1];
    }

    /* Second parallel region: add the block offset to every element of the
       corresponding block, turning the per‑block exclusive prefix into a
       global exclusive prefix. */
    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();

        const std::size_t base   = n / static_cast<std::size_t>(num_threads);
        const std::size_t extra  = n % static_cast<std::size_t>(num_threads);
        const std::size_t start  = tid * base + std::min(static_cast<std::size_t>(tid), extra);
        const std::size_t length = base + (static_cast<std::size_t>(tid) < extra ? 1 : 0);
        const std::size_t end    = start + length;

        const long long offset = block_excl[tid];
        for (std::size_t i = start; i < end; ++i) {
            prefix_before[i] += offset;
        }
    }

    /* --------------------------------------------------------------
       3. Convert exclusive prefix sums to reverse prefix (suffix) sums.
       -------------------------------------------------------------- */
    #pragma omp parallel for schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        // sum of elements after (and including) i = total - sum of elements before i
        output[i] = static_cast<int>(total - prefix_before[i]);
    }
}
